<?php
/**
 * MRL Driver Points Tally Installer
 * VERSION: v001
 * LAST MODIFIED: 11/4/2026 11:58:15 pm
 * CHANGELOG: v001 - Initial preflight, LINTGATE, backup, install, postflight and rollback.
 * Place installer in public_html/race_results/ alongside year folders.
 */
declare(strict_types=1);
date_default_timezone_set('America/New_York');
header('X-Content-Type-Options: nosniff');
header('Cache-Control: no-store, private');
$target = __DIR__ . '/mrl_driver_points_tally.php';
$backup = __DIR__ . '/mrl_driver_points_tally.rollback.bak';
$payload = base64_decode('', true);
$messages = [];
$action = isset($_POST['action']) && is_string($_POST['action']) ? $_POST['action'] : '';
$hasArchive = count(glob(__DIR__ . '/[12][0-9][0-9][0-9]', GLOB_ONLYDIR) ?: []) > 0;
$dirWritable = is_writable(__DIR__);
$targetWritable = !file_exists($target) || is_writable($target);
$backupWritable = !file_exists($backup) || is_writable($backup);
$lintAvailable = function_exists('shell_exec');
$csrf = hash_hmac('sha256', 'mrl-driver-tally-install', __FILE__ . '|' . __DIR__);
function lintFile(string $path): array {
    if (!function_exists('shell_exec')) return [false, 'LINTGATE unavailable: shell_exec disabled'];
    $result = shell_exec('php -l ' . escapeshellarg($path) . ' 2>&1');
    $output = trim((string)$result);
    return [strpos($output, 'No syntax errors detected') !== false, $output ?: 'No lint output returned'];
}
function msg(array &$messages, bool $ok, string $text): void { $messages[] = [$ok, $text]; }
if ($action !== '') {
    if (!hash_equals($csrf, (string)($_POST['token'] ?? ''))) {
        msg($messages, false, 'Invalid action token.');
    } elseif ($action === 'apply') {
        if (!$hasArchive || !$dirWritable || !$targetWritable || !$backupWritable || !$lintAvailable || !is_string($payload)) {
            msg($messages, false, 'Preflight blocked Apply. Resolve the failed checks below.');
        } else {
            $temp = tempnam(__DIR__, '.mrl_tally_');
            if ($temp === false || file_put_contents($temp, $payload, LOCK_EX) !== strlen($payload)) {
                msg($messages, false, 'Unable to create candidate file.');
            } else {
                [$lintOK, $lintText] = lintFile($temp);
                msg($messages, $lintOK, 'LINTGATE candidate: ' . $lintText);
                if ($lintOK) {
                    $previous = is_file($target) ? file_get_contents($target) : null;
                    if ($previous !== null && file_put_contents($backup, $previous, LOCK_EX) !== strlen($previous)) {
                        msg($messages, false, 'Backup failed. Apply blocked.');
                    } else {
                        $installed = @rename($temp, $target);
                        if (!$installed) $installed = file_put_contents($target, $payload, LOCK_EX) === strlen($payload);
                        if ($installed) {
                            [$postOK, $postText] = lintFile($target);
                            $postOK = $postOK && hash_file('sha256', $target) === hash('sha256', $payload);
                            msg($messages, $postOK, 'LINTGATE postflight and content verification: ' . $postText);
                            if (!$postOK) {
                                if ($previous !== null) {
                                    $restored = file_put_contents($target, $previous, LOCK_EX) === strlen($previous);
                                } else { $restored = @unlink($target); }
                                msg($messages, $restored, $restored ? 'Automatic rollback completed.' : 'Automatic rollback FAILED; manual intervention needed.');
                            } else msg($messages, true, 'Installation completed. No existing MRL scoring, cron or snapshot files were changed.');
                        } else msg($messages, false, 'Unable to install target.');
                    }
                }
            }
            if (isset($temp) && is_string($temp) && is_file($temp)) @unlink($temp);
        }
    } elseif ($action === 'rollback') {
        if (!is_file($backup)) msg($messages, false, 'No prior-version backup exists.');
        else {
            $old = file_get_contents($backup);
            if ($old === false) msg($messages, false, 'Could not read backup.');
            else {
                $tmp = tempnam(__DIR__, '.mrl_rollback_');
                if ($tmp === false || file_put_contents($tmp, $old, LOCK_EX) !== strlen($old)) msg($messages, false, 'Could not stage rollback.');
                else {
                    [$ok, $detail] = lintFile($tmp);
                    msg($messages, $ok, 'Rollback LINTGATE: ' . $detail);
                    if ($ok) {
                        $done = @rename($tmp, $target);
                        if (!$done) $done = file_put_contents($target, $old, LOCK_EX) === strlen($old);
                        msg($messages, $done, $done ? 'Previous utility restored.' : 'Rollback write failed.');
                    }
                }
                if (isset($tmp) && is_string($tmp) && is_file($tmp)) @unlink($tmp);
            }
        }
    }
}
function e($s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$checks = [
    ['Year archive folders present', $hasArchive],
    ['Installer located in writable race_results folder', $dirWritable],
    ['Target file writable or absent', $targetWritable],
    ['Rollback backup writable or absent', $backupWritable],
    ['LINTGATE shell_exec available', $lintAvailable],
    ['Embedded payload available', is_string($payload) && strlen($payload) > 1000],
];
$ready = !in_array(false, array_column($checks, 1), true);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MRL Driver Points Tally Installer</title><style>
body{font:16px Arial,sans-serif;background:#171b22;color:#e8edf5;margin:0;padding:32px}main{max-width:850px;margin:auto}h1{margin-bottom:5px}p{color:#aeb9c9;line-height:1.5}table{border-collapse:collapse;width:100%;background:#222a35}td{padding:12px;border-bottom:1px solid #374150}.pass{color:#74d99c}.fail{color:#ff8e8e}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}button,a.button{border:0;border-radius:7px;padding:12px 18px;color:#fff;font-weight:bold;cursor:pointer;text-decoration:none;display:inline-block;background:#2563eb}button.apply{background:#15803d}button.rollback{background:#b91c1c}button:disabled{opacity:.4;cursor:not-allowed}.message{background:#253040;border-radius:6px;padding:12px;margin:8px 0}.small{font-size:13px}
</style></head><body><main><h1>MRL Driver Points Tally — Installer v001</h1><p>Preflight → LINTGATE candidate → backup if replacing → Apply → LINTGATE postflight → rollback on validation failure. Only <code>mrl_driver_points_tally.php</code> is installed. Existing race snapshots and scheduled jobs remain untouched.</p><h2>Preflight</h2><table><?php foreach($checks as $check): ?><tr><td><?=e($check[0])?></td><td class="<?=$check[1]?'pass':'fail'?>"><?=$check[1]?'PASS':'FAIL'?></td></tr><?php endforeach; ?></table>
<?php foreach($messages as $message): ?><div class="message <?=$message[0]?'pass':'fail'?>"><?=e($message[1])?></div><?php endforeach; ?>
<div class="buttons"><form method="post"><input type="hidden" name="token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="apply"><button class="apply" <?=$ready?'':'disabled'?>>Run LINTGATE &amp; Apply</button></form><form method="post" onsubmit="return confirm('Restore the previous version of the tally utility?');"><input type="hidden" name="token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="rollback"><button class="rollback" <?=is_file($backup)?'':'disabled'?>>Rollback previous version</button></form><a class="button" href="mrl_driver_points_tally.php">Open tally utility</a></div>
<p class="small">First-time installation has no previous version to restore. To remove a first-time installation, delete only <code>mrl_driver_points_tally.php</code>. Remove the installer after successful installation if no longer needed.</p></main></body></html>
